package text

// Reverse satrni rune'lar bo'yicha teskari aylantiradi.
func Reverse(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}

// IsPalindrome satr teskarisiga teng ekanini tekshiradi.
func IsPalindrome(s string) bool {
	return s == Reverse(s)
}

// fayl: text_test.go
