import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("topilmadi")

type ValidationError struct{ Field string }

func (e *ValidationError) Error() string { return "noto'g'ri maydon: " + e.Field }

func find(id int) error {
	switch id {
	case 0:
		return fmt.Errorf("find(%d): %w", id, ErrNotFound)
	case -1:
		return &ValidationError{Field: "id"}
	}
	return nil
}

func main() {
	err := find(0)
	fmt.Println("Is:", errors.Is(err, ErrNotFound), "| ==:", err == ErrNotFound)

	var ve *ValidationError
	err = find(-1)
	fmt.Println("As:", errors.As(err, &ve), ve.Field)

	fmt.Println("nil xato:", find(5) == nil)
}

package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"strings"
	"unicode"
	"unicode/utf8"
)

const src = `package calc

import "testing"

func TestAdd(t *testing.T)        {}
func Test_sub(t *testing.T)       {}
func Test(t *testing.T)           {}
func Testmul(t *testing.T)        {}
func TestDiv(t *testing.T, n int) {}
func TestPtr(t testing.T)         {}
func helper(t *testing.T)         {}
`

func isTest(fn *ast.FuncDecl) bool {
	name := fn.Name.Name
	if !strings.HasPrefix(name, "Test") {
		return false
	}
	if rest := name[len("Test"):]; rest != "" {
		if r, _ := utf8.DecodeRuneInString(rest); unicode.IsLower(r) {
			return false
		}
	}
	params := fn.Type.Params.List
	if len(params) != 1 {
		return false
	}
	star, ok := params[0].Type.(*ast.StarExpr)
	if !ok {
		return false
	}
	sel, ok := star.X.(*ast.SelectorExpr)
	return ok && sel.Sel.Name == "T"
}

func main() {
	file, err := parser.ParseFile(token.NewFileSet(), "calc_test.go", src, 0)
	if err != nil {
		fmt.Println(err)
		return
	}
	for _, decl := range file.Decls {
		if fn, ok := decl.(*ast.FuncDecl); ok {
			fmt.Printf("%-8s test: %v\n", fn.Name.Name, isTest(fn))
		}
	}
}

package main

import "fmt"

// panics f panic qilsa, uning matnini va true qaytaradi.
func panics(f func()) (msg string, ok bool) {
	defer func() {
		if r := recover(); r != nil {
			msg, ok = fmt.Sprint(r), true
		}
	}()
	f()
	return "", false
}

func main() {
	zero := 0
	items := []int{1, 2, 3}
	fmt.Println(panics(func() { _ = 10 / zero }))
	fmt.Println(panics(func() { _ = items[5] }))
	fmt.Println(panics(func() { _ = items[1] }))
}

