		{"manfiy", "-3", 0, ErrNegative},
		{"harf", "abc", 0, strconv.ErrSyntax},
	}
	for _, tc := range tests {
		got, err := ParseAge(tc.in)
		ok := errors.Is(err, tc.wantErr) && got == tc.want
		fmt.Printf("%-8s got=%d err=%v ok=%v\n", tc.name, got, err, ok)
