func fieldDiff(got, want any) []string {
	gv, wv := reflect.ValueOf(got), reflect.ValueOf(want)
	var out []string
	for i := range gv.NumField() {
		g, w := gv.Field(i).Interface(), wv.Field(i).Interface()
		if !reflect.DeepEqual(g, w) {
			out = append(out, fmt.Sprintf("%s: got %v, want %v", gv.Type().Field(i).Name, g, w))
		}
	}
	return out
}

func main() {
	got := Student{"Aziz", 20, []string{"go", "sql"}, 4.5}
	want := Student{"Aziz", 21, []string{"go", "sql", "git"}, 4.5}
	for _, line := range fieldDiff(got, want) {
		fmt.Println(line)
	}
}

