func Run[In, Out any](t *testing.T, cases []Case[In, Out], f func(In) Out) {
	t.Helper()
	for _, tc := range cases {
		t.Run(tc.Name, func(t *testing.T) {
			if got := f(tc.In); !reflect.DeepEqual(got, tc.Want) {
				t.Errorf("f(%v) = %v; want %v", tc.In, got, tc.Want)
			}
		})
	}
}

func TestUpper(t *testing.T) {
	Run(t, []Case[string, string]{
		{"oddiy", "go", "GO"},
		{"bo'sh", "", ""},
	}, strings.ToUpper)
}

func TestLen(t *testing.T) {
	Run(t, []Case[string, int]{
		{"lotin", "salom", 5},
		{"kirill", "салом", 10}, // len bayt sonini beradi
	}, func(s string) int { return len(s) })
}

func main() {
	testing.Init()
	flag.Set("test.v", "true")
	tests := []testing.InternalTest{{Name: "TestUpper", F: TestUpper}, {Name: "TestLen", F: TestLen}}
	testing.Main(regexp.MatchString, tests, nil, nil)
}

