package report

import (
	"fmt"
	"strings"
)

type Item struct {
	Name  string
	Qty   int
	Price int
}

// Report buyurtmalar jadvalini matn ko'rinishida qaytaradi.
func Report(items []Item) string {
	var b strings.Builder
	total := 0
	for _, it := range items {
		sum := it.Qty * it.Price
		total += sum
		fmt.Fprintf(&b, "%-6s %2d x %6d = %7d\n", it.Name, it.Qty, it.Price, sum)
	}
	fmt.Fprintf(&b, "JAMI: %d\n", total)
	return b.String()
}

