// fayl: stack.go
package stack

type Stack struct{ items []int }

func (s *Stack) Push(n int) { s.items = append(s.items, n) }

func (s *Stack) Pop() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	n := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return n, true
}

// fayl: stack_test.go
package stack

import "testing"

type step struct {
	push   int  // 0 bo'lmasa — Push
	pop    bool // true bo'lsa — Pop
	want   int
	wantOK bool
}

func TestStackScenarios(t *testing.T) {
	tests := []struct {
		name  string
		steps []step
	}{
		{"bo'sh stekdan pop", []step{{pop: true, wantOK: false}}},
		{"LIFO tartibi", []step{{push: 1}, {push: 2}, {pop: true, want: 2, wantOK: true}, {pop: true, want: 1, wantOK: true}}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			var s Stack
			for i, st := range tc.steps {
				if st.push != 0 {
					s.Push(st.push)
					continue
				}
				got, ok := s.Pop()
				if got != st.want || ok != st.wantOK {
					t.Errorf("qadam %d: Pop() = %d, %v; want %d, %v", i, got, ok, st.want, st.wantOK)
				}
			}
		})
	}
}

