package sortcount

// BubbleSwaps pufakchali saralash jarayonidagi almashtirishlar sonini qaytaradi.
func BubbleSwaps(nums []int) int {
	swaps := 0
	for i := range nums {
		for j := 0; j < len(nums)-1-i; j++ {
			if nums[j] > nums[j+1] {
				nums[j], nums[j+1] = nums[j+1], nums[j]
				swaps++
			}
		}
	}
	return swaps
}

