package work

func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	for d := 2; d*d <= n; d++ {
		if n%d == 0 {
			return false
		}
	}
	return true
}

// CountPrimes limit gacha tub sonlar sonini hisoblaydi.
func CountPrimes(limit int) int {
	count := 0
	for n := range limit {
		if isPrime(n) {
			count++
		}
	}
	return count
}

