type Clock interface{ Now() time.Time }

type fakeClock struct{ t time.Time }

func (c *fakeClock) Now() time.Time          { return c.t }
func (c *fakeClock) Advance(d time.Duration) { c.t = c.t.Add(d) }

type entry struct {
	value   string
	expires time.Time
}

type Cache struct {
	clock Clock
	ttl   time.Duration
	items map[string]entry
}

func NewCache(c Clock, ttl time.Duration) *Cache {
	return &Cache{clock: c, ttl: ttl, items: map[string]entry{}}
}

func (c *Cache) Set(k, v string) { c.items[k] = entry{v, c.clock.Now().Add(c.ttl)} }

func (c *Cache) Get(k string) (string, bool) {
	e, ok := c.items[k]
	if !ok || !c.clock.Now().Before(e.expires) {
		return "", false
	}
	return e.value, true
}

func main() {
	clock := &fakeClock{t: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)}
	cache := NewCache(clock, time.Minute)
	cache.Set("kalit", "qiymat")

	fmt.Println(cache.Get("kalit"))
	clock.Advance(59 * time.Second)
	fmt.Println(cache.Get("kalit"))
	clock.Advance(2 * time.Second)
	fmt.Println(cache.Get("kalit"))
}

