import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
)

func GetWithRetry(url string, attempts int) (string, error) {
	var lastErr error
	for range attempts {
		resp, err := http.Get(url)
		if err == nil && resp.StatusCode == http.StatusOK {
			defer resp.Body.Close()
			b, _ := io.ReadAll(resp.Body)
			return string(b), nil
		}
		if err == nil {
			resp.Body.Close()
			lastErr = fmt.Errorf("status %d", resp.StatusCode)
		} else {
			lastErr = err
		}
	}
	return "", fmt.Errorf("%d urinishdan keyin: %w", attempts, lastErr)
}

func main() {
	var hits atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if hits.Add(1) < 3 {
			http.Error(w, "vaqtinchalik xato", http.StatusInternalServerError)
			return
		}
		fmt.Fprint(w, "tayyor")
	}))
	defer srv.Close()

	body, err := GetWithRetry(srv.URL, 5)
	fmt.Println(body, err, "| so'rovlar:", hits.Load())

	hits.Store(-100) // server doim 500 qaytaradigan holat
	_, err = GetWithRetry(srv.URL, 2)
	fmt.Println(err)
}

