// CountGoFiles fsys ichidagi .go fayllar sonini sanaydi.
func CountGoFiles(fsys fs.FS) (int, error) {
	n := 0
	err := fs.WalkDir(fsys, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() && strings.HasSuffix(path, ".go") {
			n++
		}
		return nil
	})
	return n, err
}

