// fayl: retry.go
package retry

import (
	"errors"
	"time"
)

var ErrGiveUp = errors.New("urinishlar tugadi")

// Do f ni muvaffaqiyatli bo'lguncha, eksponensial kutish bilan chaqiradi.
func Do(attempts int, f func() error) error {
	delay := time.Second
	for i := range attempts {
		if err := f(); err == nil {
			return nil
		}
		if i < attempts-1 {
			time.Sleep(delay)
			delay *= 2
		}
	}
	return ErrGiveUp
}

// fayl: retry_test.go
package retry

import (
	"errors"
	"testing"
	"testing/synctest"
	"time"
)

func TestDoBackoff(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		calls := 0
		start := time.Now()
		err := Do(4, func() error {
			calls++
			return errors.New("hali tayyor emas")
		})
		elapsed := time.Since(start)

		if !errors.Is(err, ErrGiveUp) {
			t.Errorf("err = %v", err)
		}
		if calls != 4 {
			t.Errorf("calls = %d; want 4", calls)
		}
		if elapsed != 7*time.Second { // 1 + 2 + 4
			t.Errorf("elapsed = %v; want 7s", elapsed)
		}
		t.Logf("soxta soat bo'yicha o'tgan vaqt: %v", elapsed)
	})
}

