import (
	"fmt"
	"math/rand/v2"
	"slices"
	"strings"
)

// ParsePair "kalit=qiymat" ni ajratadi (xato: '=' bo'lmasa qulaydi).
func ParsePair(s string) (string, string) {
	i := strings.IndexByte(s, '=')
	return s[:i], s[i+1:]
}

func crashes(s string) (msg string, ok bool) {
	defer func() {
		if r := recover(); r != nil {
			msg, ok = fmt.Sprint(r), true
		}
	}()
	ParsePair(s)
	return "", false
}

func mutate(r *rand.Rand, s string) string {
	b := []byte(s)
	switch r.IntN(3) {
	case 0:
		if len(b) > 0 {
			b[r.IntN(len(b))] = byte('a' + r.IntN(26))
		}
	case 1:
		b = slices.Insert(b, r.IntN(len(b)+1), byte('a'+r.IntN(26)))
	case 2:
		if len(b) > 0 {
			i := r.IntN(len(b))
			b = slices.Delete(b, i, i+1)
		}
	}
	return string(b)
}

func main() {
	r := rand.New(rand.NewPCG(7, 7))
	corpus := []string{"a=b", "kalit=qiymat"}
	for i := 1; i <= 10000; i++ {
		input := mutate(r, corpus[r.IntN(len(corpus))])
		if msg, bad := crashes(input); bad {
			fmt.Printf("%d-urinishda qulash: %q\n%s\n", i, input, msg)
			return
		}
	}
	fmt.Println("qulash topilmadi")
}

