	"bytes"
	"encoding/hex"
	"fmt"
	"math/rand/v2"
)

func main() {
	r := rand.New(rand.NewPCG(3, 4))
	failures := 0
	for range 2000 {
		data := make([]byte, r.IntN(20))
		for i := range data {
			data[i] = byte(r.IntN(256))
		}
		decoded, err := hex.DecodeString(hex.EncodeToString(data))
		if err != nil || !bytes.Equal(decoded, data) {
			failures++
		}
	}
	fmt.Println("hex round-trip xatolari:", failures)
}

package main

import (
	"fmt"
	"math"
	"math/rand/v2"
)

func myAbs(x float64) float64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	r := rand.New(rand.NewPCG(5, 6))
	mismatches := 0
	for range 10000 {
		x := (r.Float64() - 0.5) * 1e6
		if myAbs(x) != math.Abs(x) {
			mismatches++
		}
	}
	// maxsus qiymatlar: -0 va NaN
	negZero := math.Copysign(0, -1)
	fmt.Println("tasodifiy farqlar:", mismatches)
	fmt.Println("myAbs(-0) ishorasi saqlanadimi:", math.Signbit(myAbs(negZero)))
	fmt.Println("math.Abs(-0) ishorasi saqlanadimi:", math.Signbit(math.Abs(negZero)))
}

// fayl: rev.go
package rev

// Reverse satrni teskarilaydi (xato: baytlar bo'yicha).
func Reverse(s string) string {
	b := []byte(s)
	for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
		b[i], b[j] = b[j], b[i]
	}
	return string(b)
}

// fayl: rev_test.go
package rev

import (
	"testing"
	"unicode/utf8"
)

func FuzzReverse(f *testing.F) {
	f.Add("Hello, world") // seed korpus
	f.Add(" ")
	f.Add("!12345")
	f.Fuzz(func(t *testing.T, orig string) {
		rev := Reverse(orig)
		if doubleRev := Reverse(rev); orig != doubleRev {
			t.Errorf("Before: %q, after: %q", orig, doubleRev)
		}
		if utf8.ValidString(orig) && !utf8.ValidString(rev) {
			t.Errorf("Reverse yaroqsiz UTF-8 qaytardi: %q", rev)
		}
	})
}

