// fayl: rev_test.go
package rev

import (
	"testing"
	"unicode/utf8"
)

func FuzzReverse(f *testing.F) {
	f.Add("Hello, world")
	f.Add("Привет")
	f.Fuzz(func(t *testing.T, orig string) {
		if !utf8.ValidString(orig) {
			t.Skip() // yaroqsiz UTF-8 uchun xossa ma'nosiz
		}
		rev := Reverse(orig)
		if !utf8.ValidString(rev) {
			t.Errorf("yaroqsiz UTF-8: %q", rev)
		}
		if Reverse(rev) != orig {
			t.Errorf("ikki marta teskarilash: %q != %q", Reverse(rev), orig)
		}
	})
}

