package kv

import "strings"

// Parse "kalit=qiymat" ni ajratadi; kalit bo'sh bo'lsa ok=false bo'lishi kerak (hozircha xato).
func Parse(s string) (key, value string, ok bool) {
	key, value, ok = strings.Cut(s, "=")
	return key, value, ok
}

