// fayl: retry.go
package retry

import (
	"errors"
	"time"
)

var ErrGiveUp = errors.New("urinishlar tugadi")

func Do(attempts int, f func() error) error {
	delay := time.Second
	for i := range attempts {
		if f() == nil {
			return nil
		}
		if i < attempts-1 {
			time.Sleep(delay)
			delay *= 2
		}
	}
	return ErrGiveUp
}

// fayl: retry_test.go
package retry

import (
	"errors"
	"testing"
	"testing/synctest"
	"time"
)

func TestDoBackoff(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		start := time.Now()
		err := Do(4, func() error { return errors.New("hali tayyor emas") })
		if !errors.Is(err, ErrGiveUp) {
			t.Errorf("err = %v", err)
		}
		if got := time.Since(start); got != 7*time.Second {
			t.Errorf("o'tgan vaqt = %v; want 7s", got)
		}
	})
}

// fayl: job.go
package job

import (
	"context"
	"sync/atomic"
	"time"
)

type Runner struct{ Runs atomic.Int32 }

// Start har interval da Runs ni oshiradi, ctx bekor bo'lguncha.
func (r *Runner) Start(ctx context.Context, interval time.Duration) {
	go func() {
		t := time.NewTicker(interval)
		defer t.Stop()
		for {
			select {
			case <-t.C:
				r.Runs.Add(1)
			case <-ctx.Done():
				return
			}
		}
	}()
}

// fayl: job_test.go
package job

import (
	"context"
	"testing"
	"testing/synctest"
	"time"
)

func TestRunnerEvery30s(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		ctx, cancel := context.WithCancel(t.Context())
		var r Runner
		r.Start(ctx, 30*time.Second)

		time.Sleep(2 * time.Minute)
		synctest.Wait()
		cancel()

		if got := r.Runs.Load(); got != 4 {
			t.Errorf("Runs = %d; want 4", got)
		}
	})
}

