// fayl: leak.go
package leak

import "time"

// Watch har soniyada kanalga yozadi, lekin to'xtatish yo'li yo'q (leak).
func Watch() <-chan int {
	ch := make(chan int)
	go func() {
		for i := 0; ; i++ {
			time.Sleep(time.Second)
			ch <- i
		}
	}()
	return ch
}

// fayl: leak_test.go
package leak

import (
	"testing"
	"testing/synctest"
)

func TestWatch(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		ch := Watch()
		if got := <-ch; got != 0 {
			t.Errorf("birinchi qiymat = %d", got)
		}
		// goroutine hali ishlayapti: to'xtatmadik
	})
}

