	sort.Ints(out)
	return out
}

// fayl: sortx_test.go
package sortx

import (
	"sort"
	"testing"
	"testing/quick"
)

func TestSortedCopyProperties(t *testing.T) {
	isSorted := func(in []int) bool {
		return sort.IntsAreSorted(SortedCopy(in))
	}
	if err := quick.Check(isSorted, nil); err != nil {
		t.Error(err)
	}

	sameLength := func(in []int) bool {
		return len(SortedCopy(in)) == len(in)
	}
	if err := quick.Check(sameLength, nil); err != nil {
		t.Error(err)
	}
}

